window.addEventListener("DOMContentLoaded",e=>{let t=document.querySelector(".header__burger"),s=document.querySelector(".header__menu");t&&t.addEventListener("click",e=>{t.classList.toggle("active"),s.classList.toggle("active")}),window.addEventListener("click",e=>{e.target.closest(".header__menu")||e.target.closest(".header__burger")||!t.classList.contains("active")||(t.classList.toggle("active"),s.classList.toggle("active"))})});